def _is_authorized_autonomous_repair(
    pull_request: dict[str, Any],
    files: list[dict[str, Any]],
) -> bool:
    """Recognize only bounded repair PRs emitted by the trusted daily workflow.

    The same-repository branch, marker, path, and size checks prevent a fork or
    forged marker from bypassing approval for infrastructure, policy, workflow,
    secret-bearing, renamed protected files, or otherwise protected changes.
    """

    head = pull_request.get("head") or {}
    base = pull_request.get("base") or {}
    head_ref = str(head.get("ref") or "")
    head_repo = str((head.get("repo") or {}).get("full_name") or "")
    base_repo = str((base.get("repo") or {}).get("full_name") or "")
    body = str(pull_request.get("body") or "")

    if not head_repo or not base_repo or head_repo != base_repo:
        return False
    if not head_ref.startswith(AUTONOMOUS_REPAIR_BRANCH_PREFIX):
        return False
    if AUTONOMOUS_REPAIR_MARKER not in body:
        return False
    if not files or len(files) > AUTONOMOUS_REPAIR_MAX_FILES:
        return False

    for item in files:
        paths = [str(item.get("filename") or "")]
        previous = str(item.get("previous_filename") or "")
        if previous:
            paths.append(previous)
        if any(_path_is_outside_autonomous_boundary(path) for path in paths):
            return False
    return True


def _issues(bot: AmosclaudBot, *, state: str) -> list[dict[str, Any]]:
    issues = bot._request("GET", f"/repos/{bot.repository}/issues?state={state}&per_page=100")
    return issues if isinstance(issues, list) else []


def _matching_approval_issue(
    bot: AmosclaudBot,
    source: str,
    *,
    state: str = "all",
    legacy_objective: str | None = None,
) -> dict[str, Any] | None:
    marker = f"{APPROVAL_MARKER}{source} -->"
    for issue in _issues(bot, state=state):
        if issue.get("pull_request"):
            continue
        body = str(issue.get("body") or "")
        if marker not in body:
            continue
        if legacy_objective is not None and f"`{legacy_objective}`" not in body:
            continue
        return issue
    return None


def _existing_open_approval(bot: AmosclaudBot, source: str) -> int | None:
    issue = _matching_approval_issue(bot, source, state="open")
    if issue is None:
        return None
    number = issue.get("number")
    return int(number) if isinstance(number, int) else None


def _approval_comments(bot: AmosclaudBot, issue_number: int) -> list[dict[str, Any]] | None:
    """Read the complete approval audit trail. Fail closed if pagination is ambiguous."""
    all_comments: list[dict[str, Any]] = []
    for page in range(1, 51):
        comments = bot._request(
            "GET",
            f"/repos/{bot.repository}/issues/{issue_number}/comments?per_page=100&page={page}",
        )
        if not isinstance(comments, list):
            return None
        all_comments.extend(item for item in comments if isinstance(item, dict))
        if len(comments) < 100:
            return all_comments
    return None


def _is_trusted_bot_record(comment: dict[str, Any]) -> bool:
    user = comment.get("user") or {}
    login = str(user.get("login") or "").lower()
    user_type = str(user.get("type") or "").lower()
    return login in TRUSTED_BOT_LOGINS and user_type == "bot"


