        "/v1/chat/completions",
    ]
    paths: list[str] = []
    for raw in candidates:
        if not raw:
            continue
        path = f"/{raw.lstrip('/')}"
        if path not in paths:
            paths.append(path)
    return paths


def _system_prompt() -> str:
    return (
